-- L13-A1-character-facts.sql (lot A1, 2026-10-30; generated by scripts/anime/a1/gen-sql.mjs, do not edit by hand)
--
-- What:   the Otakudle facts of docs/o1/contracts/dle-a1-characters.md: 50 series_facts rows (demographic), 120 character_facts rows (118 with gender, species and role_at_debut), and 570 entity_sources rows, one per stored value. Upserts only. It touches no other table, no row of L01 to L12, no kpop row.
-- Owner:  applies the owner's answers to the A1 review. Species of Goku (saiyan), Nezuko (demon) and Denji (hybrid) depart from the contract's "species shown first" by the owner's decision. Hunter x Hunter voices are the 2011 series (Madhouse), like the studio in L04.
-- Needs:  L04 (series and characters), 011 (entity_sources.source_url and widened checks), 023 (the two tables).
-- Verify: docs/launch/o1/checks/V-L13.sql (session.sh J4); select count(*) from public.series_facts;   expect 50
--         select count(*) from public.character_facts;   expect 120
-- Undo:   L13-A1-character-facts.rollback.sql (refused once the game otakudle has a play).
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

set lock_timeout = '5s';
set client_min_messages = warning;
do $a1$ begin
  if to_regclass('public.character_facts') is null or to_regclass('public.series_facts') is null then
    raise exception 'L13: public.character_facts or public.series_facts is missing (apply 023 first)';
